from rules import resolve


def solve(data):
    return resolve(data)

def _acyclic(edges):
    graph = {}
    for source, target in edges:
        graph.setdefault(source, []).append(target)
        graph.setdefault(target, [])

    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[node] = 1
        for neighbor in graph.get(node, []):
            if not visit(neighbor):
                return False
        state[node] = 2
        return True

    return all(visit(node) for node in graph)


def resolve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    best_key = None
    best_versions = None

    def search(assigned, bounds, pending, edges):
        nonlocal best_key, best_versions

        pending = {name for name in pending if name not in assigned}
        if not pending:
            if not _acyclic(edges):
                return
            key = tuple(assigned.get(name, -1) for name in names)
            if best_key is None or key > best_key:
                best_key = key
                best_versions = dict(assigned)
            return

        name = min(pending)
        low, high = bounds.get(name, (None, None))
        for row in packages.get(name, []):
            version = row['version']
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            if low is not None and version < low:
                continue
            if high is not None and version > high:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_bounds = dict(bounds)
            next_pending = pending - {name}
            next_edges = list(edges)
            valid = True

            for dependency in row.get('deps', []):
                feature = dependency.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dependency['name']
                dep_low = dependency['min']
                dep_high = dependency['max']
                old_low, old_high = next_bounds.get(dep_name, (None, None))
                new_low = dep_low if old_low is None else max(old_low, dep_low)
                new_high = dep_high if old_high is None else min(old_high, dep_high)
                if new_low > new_high:
                    valid = False
                    break
                next_bounds[dep_name] = (new_low, new_high)
                next_edges.append((name, dep_name))
                if dep_name in next_assigned:
                    dep_version = next_assigned[dep_name]
                    if dep_version < new_low or dep_version > new_high:
                        valid = False
                        break
                else:
                    next_pending.add(dep_name)

            if valid:
                search(next_assigned, next_bounds, next_pending, next_edges)

    initial_bounds = {name: tuple(interval) for name, interval in roots.items()}
    search({}, initial_bounds, set(roots), [])
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
